function install_error_message(Throwable $ex): string {
 if($ex instanceof PDOException){
  $code=(int)($ex->errorInfo[1]??0);
  return match($code){
   1045=>'Database access was denied. Check the full cPanel database username and password, and add that user to the selected database with ALL PRIVILEGES.',
   1049=>'The database was not found. Create it in cPanel and enter its complete name including the account prefix.',
   1044,1142,1143,1227=>'The database user does not have the required privileges. In cPanel, add the user to this database with ALL PRIVILEGES.',
   2002,2003=>'The database server could not be reached. Confirm the database host and port. If localhost uses an unavailable socket, use the TCP host given by your hosting provider.',
   1071=>'The database index limit is incompatible. Use MySQL 8 or a current MariaDB version with an InnoDB page size suitable for utf8mb4 indexes.',
   1050,1061=>'An earlier installation left application tables or indexes. Use a new empty database, keeping the existing database intact.',
   default=>'Database setup could not be completed. Check the database details and privileges. The private application log contains the error for your hosting administrator.'
  };
 }
 return 'Installation could not be completed. Confirm that config and all private storage directories are writable by this hosting account. The private application log contains the error.';
}

function install_value(string $name,string $default=''): string {
 if(!in_array($name,['organisation_name','support_email','base_url','db_driver','db_host','db_port','db_name','db_user','name','email','phone'],true))return $default;
 $v=$_POST[$name]??$default;return is_scalar($v)?mb_substr((string)$v,0,250):$default;
}
